#!/usr/bin/env python3
"""Generate src/astromech_config.h from the YAML in esp32/config.

Dev-time only: the generated header is committed, so building the library needs
neither Python nor PyYAML. `make sync-config` runs this after copying config/;
`make check-config` runs it with --check to detect a stale header.
"""
import sys
from pathlib import Path

import yaml

ROOT = Path(__file__).resolve().parent.parent
CONFIG = ROOT / "config"
OUT = ROOT / "src" / "astromech_config.h"


def render() -> str:
  out = [
      "// GENERATED by tools/gen_config.py from config/ -- do not edit.",
      "// Edit the top-level config/ directory, then run `make sync-config`.",
      "#pragma once",
      "",
      '#include "astromech_types.h"',
      "",
      "namespace astromech {",
      "namespace config {",
      "",
  ]
  for p in sorted((CONFIG / "droids").glob("*.yml")):
    c = yaml.safe_load(p.read_text())
    n = p.stem
    out.append(f"static const DroidDefaults k_{n}_defaults = {{")
    out.append(f"    /*wheel_speed=*/0x{c['wheels']['speed']:02x}, "
               f"/*wheel_ramp_ms=*/{c['wheels']['motor_ramp_time']},")
    out.append(f"    /*head_speed=*/0x{c['head']['speed']:02x}, "
               f"/*head_ramp_ms=*/{c['head']['motor_ramp_time']}}};")
    out.append("")
  names = []
  for p in sorted((CONFIG / "personalities").glob("*.yml")):
    c = yaml.safe_load(p.read_text())
    n = p.stem
    names.append(n)
    out.append(f"static const Sound k_{n}_sounds[] = {{")
    for s in c["sounds"]:
      out.append(f"    {{{s['group']}, {s['sound']}, {s['ms']}}},")
    out.append("};")
    out.append(f"static const Personality k_{n} = {{\"{n}\", k_{n}_sounds,")
    out.append(f"    sizeof(k_{n}_sounds) / sizeof(k_{n}_sounds[0])}};")
    out.append("")
  out.append("}  // namespace config")
  out.append("")
  out.append("// Names of every personality above, in lookup order.")
  out.append("static const char* const kPersonalityNames[] = {")
  for n in names:
    out.append(f"    \"{n}\",")
  out.append("};")
  out.append("static const size_t kPersonalityCount =")
  out.append("    sizeof(kPersonalityNames) / sizeof(kPersonalityNames[0]);")
  out.append("")
  out.append("// Personality lookup by config file name; nullptr if unknown.")
  out.append("static inline const Personality* findPersonality(const char* name) {")
  for n in names:
    out.append(f"  if (strcmp(name, \"{n}\") == 0) return &config::k_{n};")
  out.append("  return nullptr;")
  out.append("}")
  out.append("")
  out.append("}  // namespace astromech")
  return "\n".join(out) + "\n"


def main() -> int:
  text = render()
  if "--check" in sys.argv:
    if not OUT.exists() or OUT.read_text() != text:
      print(f"ERROR: {OUT} is stale. Run 'make sync-config'.")
      return 1
    return 0
  OUT.write_text(text)
  print(f"wrote {OUT}")
  return 0


if __name__ == "__main__":
  sys.exit(main())
